insert into public.game_recipes ("id","output_item","output_qty","inputs","sale_gold","craft_seconds","sell_seconds","workshop_level","sort_order") values ('gear_hero_kingdom_3_weapon','왕도 특무 박멸검',1,'{"왕도 여명의 심장":2,"황동 장식편":10,"근위대 휘장":12,"강화석":10}',0,18000,0,3,381) on conflict (id) do update set "output_item"=excluded."output_item","output_qty"=excluded."output_qty","inputs"=excluded."inputs","sale_gold"=excluded."sale_gold","craft_seconds"=excluded."craft_seconds","sell_seconds"=excluded."sell_seconds","workshop_level"=excluded."workshop_level","sort_order"=excluded."sort_order";
