create or replace function public.game_species_template(p_family text) returns jsonb language sql immutable set search_path=public as $$select '{"slime":{"family":"slime","name":"먹물 슬라임","role":"균형","hp":145,"atk":15,"def":11,"spd":9,"crit":0.04,"evade":0.03,"power":45,"skill":"office_slime_base","description":"도장을 찍을수록 몸에 계약서 잉크가 스며드는 말랑한 신입."},"goblin":{"family":"goblin","name":"특급 배달 고블린","role":"공격","hp":100,"atk":21,"def":7,"spd":14,"crit":0.08,"evade":0.06,"power":52,"skill":"office_goblin_base","description":"용사의 등 뒤에도 정시 배송하는 계약서 배달원."},"troll":{"family":"troll","name":"철야 트롤","role":"공격","hp":175,"atk":24,"def":13,"spd":7,"crit":0.05,"evade":0.02,"power":68,"skill":"office_troll_base","description":"무거운 서류함도 한 손으로 옮기는 든든한 야간조."},"mandrake":{"family":"mandrake","name":"구급 만드라고라","role":"회복","hp":125,"atk":12,"def":9,"spd":10,"crit":0.03,"evade":0.04,"power":50,"skill":"office_mandrake_base","description":"화분 속 약초와 따뜻한 차로 동료의 근무를 이어준다."},"pixie":{"family":"pixie","name":"결재 픽시","role":"회복","hp":78,"atk":10,"def":4,"spd":17,"crit":0.03,"evade":0.12,"power":48,"skill":"office_pixie_base","description":"작은 날개로 날아다니며 가장 급한 결재부터 처리한다."},"imp":{"family":"imp","name":"화로 임프","role":"마법","hp":86,"atk":22,"def":5,"spd":11,"crit":0.06,"evade":0.04,"power":54,"skill":"office_imp_base","description":"커피를 끓이던 화로로 용사의 갑옷까지 녹이는 기술자."},"wisp":{"family":"wisp","name":"전등 위습","role":"마법","hp":76,"atk":21,"def":4,"spd":16,"crit":0.06,"evade":0.1,"power":53,"skill":"office_wisp_base","description":"낡은 탁상등 속에서 사내 마력망을 연결하는 작은 유령."},"golem":{"family":"golem","name":"금고 골렘","role":"방어","hp":240,"atk":13,"def":21,"spd":5,"crit":0.02,"evade":0.01,"power":63,"skill":"office_golem_base","description":"동료를 지키는 일이 금고를 지키는 것보다 중요하다고 배웠다."},"mimic":{"family":"mimic","name":"택배 미믹","role":"방어","hp":185,"atk":20,"def":17,"spd":6,"crit":0.04,"evade":0.01,"power":62,"skill":"office_mimic_base","description":"개봉한 인간에게 반품 불가 조항을 직접 설명하는 상자."}}'::jsonb->p_family$$;
create or replace function public.game_monster_max_hp(p_monster uuid)
returns integer language sql stable set search_path=public as $$
 select greatest(1,round(m.hp_base+(greatest(1,m.level)-1)*9*(case m.growth_grade when 'S' then 1.21 when 'A' then 1.13 when 'B' then 1.06 else 1 end)+greatest(0,m.talent-80)*2+coalesce((select sum(d.hp*(1+q.enhance_level*.08)) from game_monster_equipment q join game_item_defs d on d.id=q.item_id where q.monster_id=m.id),0)))::integer from game_monsters m where m.id=p_monster
$$;
create or replace function public.game_apply_death_xp_penalty(p_monster uuid)
returns integer language sql set search_path=public as $$select 0$$;
create or replace function public.game_boss_roll_for_site(p_player uuid,p_site text,p_chance numeric)
returns boolean language plpgsql set search_path=public as $$
declare p game_stage_progress%rowtype; result boolean;
begin
 select * into p from game_stage_progress where player_id=p_player and site_id=p_site for update;
 if not coalesce(p.boss_ready or p.boss_cleared or p.normal_battles>=500,false) then return false;end if;
 result:=p.boss_misses>=99 or random()<p_chance;
 update game_stage_progress set boss_misses=case when result then 0 else boss_misses+1 end where player_id=p_player and site_id=p_site;
 return result;
end $$;
create or replace function public.game_apply_service(p_expedition uuid)
returns jsonb language plpgsql set search_path=public as $$
declare m record; next_grade text; notices jsonb:='[]'; old_rank integer; new_rank integer;
begin
 for m in select x.* from game_expedition_members em join game_monsters x on x.id=em.monster_id where em.expedition_id=p_expedition order by em.position for update of x loop
  next_grade:=case when m.service_points+1>=2000 then 'S' when m.service_points+1>=800 then 'A' when m.service_points+1>=200 then 'B' else 'C' end;
  old_rank:=array_position(array['C','B','A','S'],m.growth_grade);new_rank:=array_position(array['C','B','A','S'],next_grade);
  update game_monsters set service_points=service_points+1,growth_grade=case when new_rank>old_rank then next_grade else growth_grade end where id=m.id;
  if new_rank>old_rank then notices:=notices||jsonb_build_array(jsonb_build_object('monsterId',m.id,'name',m.name,'grade',next_grade));end if;
 end loop;
 return notices;
end $$;
create or replace function public.game_auto_evolve(p_expedition uuid)
returns jsonb language plpgsql set search_path=public as $$
declare m record; evo game_evolution_defs%rowtype; notices jsonb:='[]';
begin
 for m in select x.* from game_expedition_members em join game_monsters x on x.id=em.monster_id where em.expedition_id=p_expedition order by em.position for update of x loop
  select * into evo from game_evolution_defs where base_family=m.family and from_form_id=m.form_id and required_level<=m.level
  order by (id=coalesce(m.evolution_plan->>m.form_id,'')) desc,id limit 1;
  if not found then continue;end if;
  update game_monsters set form_id=evo.target_form_id,evolution_tier=evo.tier,skill_id=evo.skill_id,name=evo.target_name,
   hp_base=greatest(1,round(hp_base*evo.hp_mult)),atk_base=greatest(1,round(atk_base*evo.atk_mult)),def_base=greatest(0,round(def_base*evo.def_mult)),
   spd_base=greatest(1,round(spd_base*evo.spd_mult)),power_base=greatest(1,round(power_base*evo.power_mult)),
   crit_base=least(.45,crit_base+evo.crit_add),evade_base=least(.35,evade_base+evo.evade_add),evolved_at=now() where id=m.id;
  notices:=notices||jsonb_build_array(jsonb_build_object('monsterId',m.id,'name',evo.target_name,'tier',evo.tier));
 end loop;
 return notices;
end $$;
create or replace function public.game_set_idle_policy(p_player uuid,p_settings jsonb)
returns boolean language plpgsql set search_path=public as $$
begin
 perform pg_advisory_xact_lock(hashtextextended('game_tick_all',0));
 if jsonb_typeof(p_settings)<>'object' then raise exception 'invalid_settings';end if;
 update game_players set idle_automation=coalesce((p_settings->>'idle_automation')::boolean,idle_automation),
 auto_reinvest=coalesce((p_settings->>'auto_reinvest')::boolean,auto_reinvest),auto_advance=coalesce((p_settings->>'auto_advance')::boolean,auto_advance),auto_equip=coalesce((p_settings->>'auto_equip')::boolean,auto_equip) where device_id=p_player;
 return found;
end $$;
create or replace function public.game_plan_evolution(p_player uuid,p_monster uuid,p_evolution text)
returns boolean language plpgsql set search_path=public as $$
declare evo game_evolution_defs%rowtype;
begin
 select d.* into evo from game_evolution_defs d join game_monsters m on m.family=d.base_family where m.id=p_monster and m.player_id=p_player and d.id=p_evolution;
 if not found then raise exception 'evolution_invalid';end if;
 update game_monsters set evolution_plan=jsonb_set(evolution_plan,array[evo.from_form_id],to_jsonb(p_evolution),true) where id=p_monster and player_id=p_player;
 return true;
end $$;
create or replace function public.game_equipment_score(p_item text,p_family text,p_level integer default 0)
returns numeric language sql stable set search_path=public as $$
 select (atk*(case when p_family in ('golem','mimic','mandrake','pixie') then 1.5 else 3 end)+hp*(case when p_family in ('golem','mimic') then .3 else .15 end)+def*(case when p_family in ('golem','mimic') then 3 else 1.5 end)+spd*2+crit*100+evade*100+human_damage*160)*(1+greatest(0,p_level)*.08) from game_item_defs where id=p_item
$$;
create or replace function public.game_auto_equip(p_expedition uuid)
returns void language plpgsql set search_path=public as $$
declare m record; slot_name text; chosen text; old_item text; old_level integer; old_score numeric; new_score numeric;
begin
 for m in select x.* from game_expedition_members em join game_monsters x on x.id=em.monster_id join game_players p on p.device_id=x.player_id where em.expedition_id=p_expedition and p.auto_equip order by em.position loop
  foreach slot_name in array array['weapon','armor','accessory'] loop
   select item_id,enhance_level into old_item,old_level from game_monster_equipment where monster_id=m.id and slot=slot_name;
   old_score:=coalesce(game_equipment_score(old_item,m.family,old_level),0);
   select d.id,game_equipment_score(d.id,m.family,0) into chosen,new_score from game_inventory i join game_item_defs d on d.id=i.item_id where i.player_id=m.player_id and i.qty>0 and d.kind='equipment' and d.slot=slot_name order by game_equipment_score(d.id,m.family,0) desc,d.id limit 1;
   if chosen is not null and new_score>old_score*1.05 and (old_item is null or game_inventory_accepts(m.player_id,old_item)) then perform game_equip_item(m.player_id,m.id,chosen);end if;
  end loop;
 end loop;
end $$;
-- Internal helpers can only be called by the authenticated Edge service / cron.
revoke all on function public.game_monster_max_hp(uuid),public.game_boss_roll_for_site(uuid,text,numeric),public.game_apply_service(uuid),public.game_auto_evolve(uuid),public.game_set_idle_policy(uuid,jsonb),public.game_plan_evolution(uuid,uuid,text),public.game_equipment_score(text,text,integer),public.game_auto_equip(uuid) from public,anon,authenticated;
grant execute on function public.game_monster_max_hp(uuid),public.game_boss_roll_for_site(uuid,text,numeric),public.game_apply_service(uuid),public.game_auto_evolve(uuid),public.game_set_idle_policy(uuid,jsonb),public.game_plan_evolution(uuid,uuid,text),public.game_equipment_score(text,text,integer),public.game_auto_equip(uuid) to service_role;

create or replace function public.game_storage_capacity(p_player uuid)
returns integer language sql stable set search_path=public as $$
 select case storage_level when 1 then 160 when 2 then 240 when 3 then 360 when 4 then 520 else 750 end from game_players where device_id=p_player
$$;
create or replace function public.game_finish_idle_jobs(p_player uuid,p_at timestamptz)
returns integer language plpgsql set search_path=public as $$
declare j record; n integer:=0;
begin
 for j in select * from game_craft_jobs where player_id=p_player and status in ('running','queued','ready') and finish_at<=p_at order by finish_at for update loop
  if game_inventory_accepts(p_player,j.output_item) then
   insert into game_inventory(player_id,item_id,qty) values(p_player,j.output_item,j.output_qty) on conflict(player_id,item_id) do update set qty=game_inventory.qty+excluded.qty;
   update game_craft_jobs set status='done',completed_at=finish_at where id=j.id;n:=n+1;
  else update game_craft_jobs set status='ready',completed_at=finish_at where id=j.id;end if;
 end loop;
 for j in select * from game_sell_jobs where player_id=p_player and status in ('running','queued','ready') and finish_at<=p_at order by finish_at for update loop
  update game_players set gold=gold+j.sale_gold,idle_receipt=jsonb_set(idle_receipt,'{gold}',to_jsonb(coalesce((idle_receipt->>'gold')::bigint,0)+j.sale_gold),true) where device_id=p_player;
  update game_sell_jobs set status='done',completed_at=finish_at where id=j.id;n:=n+1;
 end loop;
 update game_craft_jobs set status='running' where player_id=p_player and status='queued' and started_at<=p_at and finish_at>p_at;
 update game_sell_jobs set status='running' where player_id=p_player and status='queued' and started_at<=p_at and finish_at>p_at;
 return n;
end $$;
create or replace function public.game_process_economy()
returns integer language plpgsql set search_path=public as $$
declare p record;n integer:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('game_tick_all',0));
 for p in select distinct player_id from (select player_id from game_craft_jobs where status in ('running','queued','ready') union select player_id from game_sell_jobs where status in ('running','queued','ready')) q loop n:=n+game_finish_idle_jobs(p.player_id,now());end loop;
 return n;
end $$;
create or replace function public.game_run_idle_economy(p_player uuid,p_at timestamptz)
returns integer language plpgsql set search_path=public as $$
declare p game_players%rowtype;r record;kv record;units integer;available bigint;start_at timestamptz;stock record;n integer:=0;needed integer;target integer;facility text;cost bigint;level_now integer;used integer;
begin
 select * into p from game_players where device_id=p_player for update;
 if p.idle_last_at is not null and p_at<p.idle_last_at+interval '30 seconds' then return 0;end if;
 update game_players set idle_last_at=p_at where device_id=p_player;
 n:=game_finish_idle_jobs(p_player,p_at);
 if not p.idle_automation then return n;end if;
 -- Automatically reinvest only where content or warehouse space requires it.
 select coalesce(max(s.unlock_order),1) into target from game_hunt_sites s where s.unlock_order=1 or exists(select 1 from game_stage_progress g join game_hunt_sites prev on prev.id=g.site_id where g.player_id=p_player and g.boss_cleared and prev.unlock_order=s.unlock_order-1);
 select count(*) into used from game_inventory where player_id=p_player and qty>0;
 if p.auto_reinvest then
  foreach facility in array array['workshop','storage'] loop
   level_now:=case facility when 'workshop' then p.workshop_level else p.storage_level end;
   needed:=case facility when 'workshop' then ceil(target/2.0)::integer else case when used>=game_storage_capacity(p_player)-12 then least(5,p.storage_level+1) else p.storage_level end end;
   cost:=(case facility when 'workshop' then 1600 else 1200 end)*power(3::numeric,level_now-1);
   if level_now<needed and p.gold>=cost then perform game_upgrade_facility(p_player,facility,level_now);select * into p from game_players where device_id=p_player;end if;
  end loop;
 end if;
 begin perform game_collect_loot(p_player,null);exception when raise_exception then if sqlerrm<>'storage_full' then raise;end if;end;
 -- Finished company goods only. Equipment and catalysts never enter auto sales.
 if not exists(select 1 from game_sell_jobs where player_id=p_player and status in ('running','queued')) then
  select i.item_id,i.qty,recipe.sale_gold,recipe.sell_seconds into stock from game_inventory i join game_recipes recipe on recipe.output_item=i.item_id where i.player_id=p_player and i.qty>0 and recipe.sale_gold>0 order by recipe.sort_order desc limit 1;
  if found then
   units:=least(10,stock.qty);update game_inventory set qty=qty-units where player_id=p_player and item_id=stock.item_id;
   insert into game_sell_jobs(player_id,item_id,sale_gold,quantity,started_at,finish_at,status) values(p_player,stock.item_id,stock.sale_gold*units,units,p_at,p_at+make_interval(secs=>stock.sell_seconds*units),'running');
  else
   select i.item_id,i.qty,d.sale_gold,d.sell_seconds into stock from game_inventory i join game_item_defs d on d.id=i.item_id where i.player_id=p_player and i.qty>60 and d.kind='material' and d.sale_gold>0 and not coalesce((d.acquisition->>'catalyst')::boolean,false) order by i.qty desc,i.item_id limit 1;
   if found then units:=least(20,stock.qty-60);update game_inventory set qty=qty-units where player_id=p_player and item_id=stock.item_id;
    insert into game_sell_jobs(player_id,item_id,sale_gold,quantity,started_at,finish_at,status) values(p_player,stock.item_id,stock.sale_gold*units,units,p_at,p_at+make_interval(secs=>stock.sell_seconds*units),'running');end if;
  end if;
 end if;
 if not exists(select 1 from game_craft_jobs where player_id=p_player and status in ('running','queued')) then
  for r in select * from game_recipes where sale_gold>0 and workshop_level<=p.workshop_level order by sale_gold::numeric/greatest(1,craft_seconds) desc,sort_order loop
   units:=5;
   for kv in select key,value::integer amount from jsonb_each_text(r.inputs) loop
    select coalesce(max(qty),0) into available from game_inventory where player_id=p_player and item_id=kv.key;
    units:=least(units,greatest(0,floor((available-12)::numeric/kv.amount)::integer));
   end loop;
   if units<1 then continue;end if;
   for kv in select key,value::integer amount from jsonb_each_text(r.inputs) loop update game_inventory set qty=qty-kv.amount*units where player_id=p_player and item_id=kv.key;end loop;
   insert into game_craft_jobs(player_id,recipe_id,output_item,output_qty,batch_qty,started_at,finish_at,status,materials_spent)
   values(p_player,r.id,r.output_item,r.output_qty*units,units,p_at,p_at+make_interval(secs=>r.craft_seconds*units),'running',(select jsonb_object_agg(key,to_jsonb(value::integer*units)) from jsonb_each_text(r.inputs)));
   exit;
  end loop;
 end if;
 delete from game_inventory where player_id=p_player and qty<=0;
 return n;
end $$;
-- Auto-completion is now the common rule, including older connected clients.
create or replace function public.game_enable_manual_economy_claim()
returns boolean language plpgsql security definer set search_path=public as $$
begin if auth.uid() is null then raise exception 'unauthorized';end if;return true;end $$;
-- Actual sale duration must agree with the catalog; equipment recipes cannot sell.
create or replace function public.game_start_sell(p_player uuid,p_item text,p_qty integer)
returns uuid language plpgsql set search_path=public as $$
declare r record;d record;have bigint;job_id uuid;unit_price integer;unit_seconds integer;scheduled_start timestamptz;capacity integer;
begin
 perform pg_advisory_xact_lock(hashtextextended('game_tick_all',0));perform game_process_economy();
 if coalesce(p_qty,0)<1 then raise exception 'quantity_invalid';end if;
 select * into d from game_item_defs where id=p_item;
 if d.kind='equipment' then raise exception 'not_sellable';end if;
 select * into r from game_recipes where output_item=p_item and sale_gold>0 order by sort_order limit 1;
 if r.id is not null then unit_price:=r.sale_gold;unit_seconds:=greatest(1,r.sell_seconds);
 elsif d.kind='material' and d.sale_gold>0 then unit_price:=d.sale_gold;unit_seconds:=greatest(1,d.sell_seconds);
 else raise exception 'not_sellable';end if;
 select shop_level+4 into capacity from game_players where device_id=p_player;
 if (select count(*) from game_sell_jobs where player_id=p_player and status in ('running','queued'))>=capacity then raise exception 'sell_queue_full';end if;
 select qty into have from game_inventory where player_id=p_player and item_id=p_item for update;
 if coalesce(have,0)<p_qty then raise exception 'item_missing';end if;
 update game_inventory set qty=qty-p_qty where player_id=p_player and item_id=p_item;delete from game_inventory where player_id=p_player and qty<=0;
 select greatest(now(),coalesce(max(finish_at),now())) into scheduled_start from game_sell_jobs where player_id=p_player and status in ('running','queued');
 insert into game_sell_jobs(player_id,item_id,sale_gold,quantity,started_at,finish_at,status) values(p_player,p_item,unit_price*p_qty,p_qty,scheduled_start,scheduled_start+make_interval(secs=>unit_seconds*p_qty),case when scheduled_start<=now() then 'running' else 'queued' end) returning id into job_id;
 return job_id;
end $$;
revoke all on function public.game_finish_idle_jobs(uuid,timestamptz),public.game_run_idle_economy(uuid,timestamptz) from public,anon,authenticated;
grant execute on function public.game_finish_idle_jobs(uuid,timestamptz),public.game_run_idle_economy(uuid,timestamptz) to service_role;

create or replace function public.game_process_expedition_action(p_expedition uuid)
returns jsonb language plpgsql set search_path=public as $$
declare e game_expeditions%rowtype;m record;st jsonb;hp jsonb;mx jsonb;result jsonb;at_time timestamptz;max_hp integer;cur_hp integer;remaining integer;revived jsonb:='[]';promotions jsonb:='[]';evolutions jsonb:='[]';next_site text;policy game_players%rowtype;
begin
 select * into e from game_expeditions where id=p_expedition and active for update;
 if not found then return jsonb_build_object('type','inactive');end if;
 at_time:=e.last_tick_at+interval '2 seconds';
 select * into policy from game_players where device_id=e.player_id;
 st:=coalesce(e.battle_state,'{}');hp:=coalesce(st->'partyHp','{}');mx:=coalesce(st->'partyMaxHp','{}');
 for m in select x.* from game_expedition_members em join game_monsters x on x.id=em.monster_id where em.expedition_id=e.id order by em.position for update of x loop
  max_hp:=game_monster_max_hp(m.id);cur_hp:=least(max_hp,coalesce(m.field_hp,(hp->>m.id::text)::integer,max_hp));remaining:=m.recovery_actions;
  if cur_hp<=0 then
   if remaining<=0 then remaining:=12;end if;
   remaining:=remaining-1;
   if remaining=0 then cur_hp:=max_hp;revived:=revived||jsonb_build_array(jsonb_build_object('monsterId',m.id,'name',m.name));end if;
  end if;
  update game_monsters set field_hp=cur_hp,recovery_actions=remaining where id=m.id;
  hp:=jsonb_set(hp,array[m.id::text],to_jsonb(cur_hp),true);mx:=jsonb_set(mx,array[m.id::text],to_jsonb(max_hp),true);
 end loop;
 st:=st||jsonb_build_object('partyHp',hp,'partyMaxHp',mx,'revived',revived);
 update game_expeditions set battle_state=st,idle_actions=idle_actions+1 where id=e.id;
 if e.regroup_remaining>0 then
  remaining:=e.regroup_remaining-1;
  if remaining=0 then
   hp:=mx;
   update game_monsters member_row set field_hp=game_monster_max_hp(member_row.id),recovery_actions=0 from game_expedition_members em where em.monster_id=member_row.id and em.expedition_id=e.id;
  end if;
  result:=jsonb_build_object('type',case when remaining=0 then 'restart' else 'regroup' end,'remaining',remaining,'partyHp',hp,'partyMaxHp',mx,'revived',revived);
  update game_expeditions set regroup_remaining=remaining,phase=case when remaining=0 then '자동 재출정' else '자동 재정비' end,battle_state=st||jsonb_build_object('active',false,'partyHp',hp),event_state=jsonb_build_object('type','regroup','text',case when remaining=0 then '전원 회복 · 박멸조가 자동으로 다시 출발합니다' else '전원 재정비 · '||remaining||'행동 후 자동 재출정' end,'t',at_time),battle_log=(select jsonb_agg(value) from (select value from jsonb_array_elements(jsonb_build_array(result)||e.battle_log) limit 20) x) where id=e.id;
 else
  -- Changes that alter stats happen between fights, with no manual recall needed.
  if not coalesce((st->>'active')::boolean,false) then
   evolutions:=game_auto_evolve(e.id);
   if policy.auto_equip then perform game_auto_equip(e.id);end if;
  end if;
  result:=game_process_expedition_action_core(e.id);
  select battle_state into st from game_expeditions where id=e.id;
  for m in select x.* from game_expedition_members em join game_monsters x on x.id=em.monster_id where em.expedition_id=e.id loop
   cur_hp:=greatest(0,coalesce((st->'partyHp'->>m.id::text)::integer,m.field_hp,game_monster_max_hp(m.id)));
   update game_monsters set field_hp=cur_hp,recovery_actions=case when cur_hp=0 and m.field_hp>0 then 12 else m.recovery_actions end where id=m.id;
  end loop;
  if result->>'type'='battle-end' then
   promotions:=game_apply_service(e.id);evolutions:=evolutions||game_auto_evolve(e.id);
   if result->>'result'='loss' then
    update game_expeditions set active=true,regroup_remaining=15,phase='자동 재정비',event_state=jsonb_build_object('type','regroup','text','박멸조 전멸 · 15행동 재정비 후 자동 재출정','t',at_time) where id=e.id;
   elsif coalesce((result->>'boss')::boolean,false) and policy.auto_advance then
    select nxt.id into next_site from game_hunt_sites cur join game_hunt_sites nxt on nxt.unlock_order=cur.unlock_order+1 where cur.id=e.site_id and not exists(select 1 from game_expeditions other where other.player_id=e.player_id and other.site_id=nxt.id and other.active and other.id<>e.id);
    if next_site is not null then update game_expeditions set site_id=next_site,phase='다음 챕터 이동',event_state=jsonb_build_object('type','advance','text','다음 챕터로 자동 진출합니다','t',at_time) where id=e.id;end if;
   end if;
  end if;
 end if;
 perform game_run_idle_economy(e.player_id,at_time);
 return result||jsonb_build_object('revived',revived,'promotions',promotions,'evolutions',evolutions,'advancedTo',next_site);
end $$;
revoke all on function public.game_process_expedition_action_core(uuid) from public,anon,authenticated;
grant execute on function public.game_process_expedition_action_core(uuid) to service_role;
create or replace function public.game_process_expeditions()
returns integer language plpgsql set search_path=public as $$
declare e record;attempts integer;i integer;n integer:=0;
begin
 for e in select id,last_tick_at from game_expeditions where active order by last_tick_at,id for update skip locked loop
  attempts:=least(20,greatest(0,floor(extract(epoch from(now()-e.last_tick_at))/2)::integer));
  for i in 1..attempts loop
   perform game_process_expedition_action(e.id);
   update game_expeditions set last_tick_at=last_tick_at+interval '2 seconds',updated_at=now() where id=e.id;n:=n+1;
  end loop;
 end loop;
 return n;
end $$;
create or replace function public.game_tick_all()
returns integer language plpgsql set search_path=public as $$
declare n integer:=0;p record;
begin
 if not pg_try_advisory_xact_lock(hashtextextended('game_tick_all',0)) then return 0;end if;
 n:=n+game_spawn_candidates();n:=n+game_process_expeditions();n:=n+game_process_defense();
 -- An active expedition owns its simulation clock. Idle companies still finish jobs.
 for p in select device_id from game_players where not exists(select 1 from game_expeditions e where e.player_id=game_players.device_id and e.active) loop n:=n+game_run_idle_economy(p.device_id,now());end loop;
 return n;
end $$;
revoke all on function public.game_process_expedition_action(uuid),public.game_process_expeditions(),public.game_tick_all() from public,anon,authenticated;
grant execute on function public.game_process_expedition_action(uuid),public.game_process_expeditions(),public.game_tick_all() to service_role;

create or replace function public.game_sync_candidate_species_name()
returns trigger language plpgsql set search_path=public as $$
begin new.name:=coalesce(game_species_template(new.family)->>'name',new.name);return new;end $$;
create or replace function public.game_sync_monster_form_name()
returns trigger language plpgsql set search_path=public as $$
declare form_name text;form_skill text;
begin
 select target_name,skill_id into form_name,form_skill from game_evolution_defs where target_form_id=new.form_id limit 1;
 new.name:=coalesce(form_name,game_species_template(new.family)->>'name',new.name);
 new.skill_id:=coalesce(form_skill,game_species_template(new.family)->>'skill',new.skill_id);
 return new;
end $$;
update public.game_monsters set name=name; -- name/skill trigger maps every current form without resetting stats
update public.game_candidates set name=name;

-- Separate idle defense: stationed employees intercept non-attacking heroes.
create table if not exists public.game_defense (
 player_id uuid primary key references public.game_players(device_id) on delete cascade,
 stage integer not null default 1 check(stage between 1 and 50),highest_stage integer not null default 1 check(highest_stage between 1 and 50),
 boss_auto boolean not null default false,wave_number bigint not null default 0,wins bigint not null default 0,losses bigint not null default 0,
 traps integer not null default 0 check(traps between 0 and 25),gas integer not null default 0 check(gas between 0 and 25),slow integer not null default 0 check(slow between 0 and 25),arcane integer not null default 0 check(arcane between 0 and 25),
 wave jsonb not null default '{}'::jsonb,last_event jsonb not null default '{}'::jsonb,reward_vault jsonb not null default '{}'::jsonb,last_tick_at timestamptz not null default now()
);
alter table public.game_defense enable row level security;
revoke all on public.game_defense from anon,authenticated;
grant all on public.game_defense to service_role;
insert into public.game_defense(player_id) select device_id from public.game_players on conflict do nothing;
create or replace function public.game_defense_snapshot(p_player uuid)
returns jsonb language sql stable set search_path=public as $$
 select coalesce((select to_jsonb(d) from game_defense d where d.player_id=p_player),jsonb_build_object('stage',1,'highest_stage',1,'boss_auto',false,'wave',jsonb_build_object(),'traps',0,'gas',0,'slow',0,'arcane',0,'wins',0,'losses',0))
$$;
create or replace function public.game_defense_upgrade(p_player uuid,p_kind text,p_expected integer)
returns jsonb language plpgsql set search_path=public as $$
declare d game_defense%rowtype;lv integer;price bigint;gold_now bigint;
begin
 perform pg_advisory_xact_lock(hashtextextended('game_tick_all',0));
 if p_kind not in ('traps','gas','slow','arcane') then raise exception 'facility';end if;
 insert into game_defense(player_id) values(p_player) on conflict do nothing;
 select * into d from game_defense where player_id=p_player for update;lv:=(to_jsonb(d)->>p_kind)::integer;
 if lv<>p_expected then raise exception 'facility_changed';end if;if lv>=25 then raise exception 'max_level';end if;
 price:=ceil((case p_kind when 'traps' then 120 when 'gas' then 180 when 'slow' then 240 else 300 end)*power(1.7::numeric,lv));
 select gold into gold_now from game_players where device_id=p_player for update;if gold_now<price then raise exception 'gold_short';end if;
 update game_players set gold=gold-price where device_id=p_player;
 execute format('update game_defense set %I=$1 where player_id=$2',p_kind) using lv+1,p_player;
 return jsonb_build_object('kind',p_kind,'level',lv+1,'cost',price);
end $$;
create or replace function public.game_defense_command(p_player uuid,p_action text,p_stage integer default null)
returns boolean language plpgsql set search_path=public as $$
declare d game_defense%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('game_tick_all',0));insert into game_defense(player_id) values(p_player) on conflict do nothing;
 select * into d from game_defense where player_id=p_player for update;
 if p_action='boss-auto' then update game_defense set boss_auto=true,wave='{}',last_event=jsonb_build_object('type','challenge','text','보스 연속 도전 시작 · 실패할 때까지 다음 단계 도전') where player_id=p_player;
 elsif p_action='stop-boss' then update game_defense set boss_auto=false,wave='{}' where player_id=p_player;
 elsif p_action='stage' then
  if p_stage is null or p_stage<1 or p_stage>d.highest_stage then raise exception 'locked';end if;
  update game_defense set stage=p_stage,boss_auto=false,wave='{}',last_event=jsonb_build_object('type','stage','text',p_stage||'단계 반복 방어') where player_id=p_player;
 else raise exception 'invalid_action';end if;
 return true;
end $$;
create or replace function public.game_defense_action(p_player uuid)
returns jsonb language plpgsql set search_path=public as $$
declare d game_defense%rowtype;w jsonb;heroes jsonb;hero jsonb;foe jsonb;next_heroes jsonb:='[]';attacks jsonb:='[]';m record;total_damage numeric:=0;damage numeric;hp numeric;pos numeric;progress numeric;remaining integer;target integer;wave_stage integer;is_boss boolean;escaped boolean:=false;all_dead boolean:=true;site game_hunt_sites%rowtype;loot_row jsonb;drops jsonb:='{}';entry record;qty integer;result jsonb;clock_at timestamptz;
begin
 select * into d from game_defense where player_id=p_player for update;if not found then return '{}';end if;
 clock_at:=d.last_tick_at+interval '2 seconds';w:=d.wave;
 -- Attack power deliberately depends on evolution, grade and level, not expedition gear.
 for m in select * from game_monsters x where x.player_id=p_player and x.released_at is null and not exists(select 1 from game_expedition_members em join game_expeditions e on e.id=em.expedition_id where em.monster_id=x.id and e.active) order by x.created_at loop
  damage:=(8+m.level*3)*(1+coalesce(m.evolution_tier,0)*.75)*(case m.growth_grade when 'S' then 1.65 when 'A' then 1.35 when 'B' then 1.15 else 1 end);
  total_damage:=total_damage+damage;attacks:=attacks||jsonb_build_array(jsonb_build_object('monsterId',m.id,'family',m.family,'damage',round(damage)));
 end loop;
 if coalesce((w->>'active')::boolean,false)=false then
  is_boss:=d.boss_auto;wave_stage:=case when is_boss then least(50,d.stage+1) else d.stage end;
  select * into site from game_hunt_sites where unlock_order=least(5,1+(wave_stage-1)/10);
  heroes:='[]';
  for target in 1..(case when is_boss then 1 else 3 end) loop
   hp:=round((120+wave_stage*18)*power(1.095::numeric,wave_stage-1)*(case when is_boss then 5 else 1 end));
   heroes:=heroes||jsonb_build_array(jsonb_build_object('id',target,'name',case when is_boss then site.boss_name else site.enemy_names[1+((d.wave_number+target)::integer%4)] end,'hp',hp,'maxHp',hp,'position',-(target-1)*.12));
  end loop;
  w:=jsonb_build_object('active',true,'boss',is_boss,'stage',wave_stage,'site',site.id,'heroes',heroes,'tick',0,'at',clock_at,'duration',60);
  update game_defense set wave=w,wave_number=wave_number+1,last_event=jsonb_build_object('type','wave','text',case when is_boss then wave_stage||'단계 보스 침입' else wave_stage||'단계 용사 침입' end,'at',clock_at) where player_id=p_player;
  return w;
 end if;
 heroes:=w->'heroes';is_boss:=(w->>'boss')::boolean;wave_stage:=(w->>'stage')::integer;
 progress:=1.0/(30+least(20,d.slow));target:=null;pos:=-999;
 -- Focus the living hero nearest the throne; poison continues on every invader.
 for hero in select value from jsonb_array_elements(heroes) loop if (hero->>'hp')::numeric>0 and (hero->>'position')::numeric>=pos then target:=(hero->>'id')::integer;pos:=(hero->>'position')::numeric;end if;end loop;
 for hero in select value from jsonb_array_elements(heroes) loop
  hp:=(hero->>'hp')::numeric;pos:=(hero->>'position')::numeric;
  if hp>0 then
   pos:=pos+progress;damage:=d.gas*(3+wave_stage*.3);
   if (hero->>'id')::integer=target and pos>=0 then damage:=damage+total_damage+d.arcane*10;end if;
   if floor(greatest(0,pos-progress)*4)<floor(greatest(0,pos)*4) then damage:=damage+d.traps*(20+wave_stage);end if;
   hp:=greatest(0,hp-damage);
   if hp>0 then all_dead:=false;if pos>=1 then escaped:=true;end if;end if;
  end if;
  next_heroes:=next_heroes||jsonb_build_array(hero||jsonb_build_object('hp',round(hp),'position',least(1,pos)));
 end loop;
 w:=w||jsonb_build_object('heroes',next_heroes,'tick',(w->>'tick')::integer+1,'at',clock_at,'attacks',attacks);
 if escaped or all_dead then
  w:=w||jsonb_build_object('active',false,'result',case when escaped then 'loss' else 'win' end);
  if escaped then
   update game_defense set losses=losses+1,boss_auto=case when is_boss then false else boss_auto end,last_event=jsonb_build_object('type','loss','boss',is_boss,'text',case when is_boss then '보스 돌파 · 연속 도전 중단, 직전 단계 반복' else '용사 도달 · 이번 웨이브 보상 없음' end,'at',clock_at) where player_id=p_player;
  else
   select * into site from game_hunt_sites where id=w->>'site';
   -- A defense wave rolls one encounter table at 25% of exploration probabilities.
   select jsonb_agg(value||jsonb_build_object('chance',(value->>'chance')::numeric*.25)) into loot_row from jsonb_array_elements(site.loot);
   drops:=game_roll_campaign_drops(loot_row,case when is_boss then site.boss_name else heroes->0->>'name' end,0);
   update game_defense set wins=wins+1,stage=case when is_boss then wave_stage else stage end,highest_stage=greatest(highest_stage,wave_stage),boss_auto=case when is_boss and wave_stage=50 then false else boss_auto end,last_event=jsonb_build_object('type','win','boss',is_boss,'text',case when is_boss then wave_stage||'단계 보스 격퇴 · 다음 보스 도전' else '용사 격퇴 · 전리품 확인' end,'drops',drops,'at',clock_at) where player_id=p_player;
   for entry in select key,value::integer qty from jsonb_each_text(drops) loop update game_defense set reward_vault=jsonb_set(reward_vault,array[entry.key],to_jsonb(coalesce((reward_vault->>entry.key)::integer,0)+entry.qty),true) where player_id=p_player;end loop;
  end if;
 end if;
 update game_defense set wave=w where player_id=p_player;
 -- Completed rewards stay in a vault when the warehouse is full, without rerolls.
 for entry in select key,value::integer qty from game_defense d2 cross join lateral jsonb_each_text(d2.reward_vault) where d2.player_id=p_player loop
  if game_inventory_accepts(p_player,entry.key) then
   insert into game_inventory(player_id,item_id,qty) values(p_player,entry.key,entry.qty) on conflict(player_id,item_id) do update set qty=game_inventory.qty+excluded.qty;
   update game_defense set reward_vault=reward_vault-entry.key where player_id=p_player;
  end if;
 end loop;
 return w;
end $$;
create or replace function public.game_process_defense()
returns integer language plpgsql set search_path=public as $$
declare d record;n integer:=0;steps integer;i integer;
begin
 insert into game_defense(player_id) select device_id from game_players on conflict do nothing;
 for d in select player_id,last_tick_at from game_defense order by last_tick_at for update skip locked loop
  steps:=least(20,greatest(0,floor(extract(epoch from(now()-d.last_tick_at))/2)::integer));
  for i in 1..steps loop perform game_defense_action(d.player_id);update game_defense set last_tick_at=last_tick_at+interval '2 seconds' where player_id=d.player_id;n:=n+1;end loop;
 end loop;
 return n;
end $$;
revoke all on function public.game_defense_snapshot(uuid),public.game_defense_upgrade(uuid,text,integer),public.game_defense_command(uuid,text,integer),public.game_defense_action(uuid),public.game_process_defense() from public,anon,authenticated;
grant execute on function public.game_defense_snapshot(uuid),public.game_defense_upgrade(uuid,text,integer),public.game_defense_command(uuid,text,integer),public.game_defense_action(uuid),public.game_process_defense() to service_role;
